#include "mygames/outbox_dispatch.h"
#include <stdbool.h>
#include <stdint.h>
#include <string.h>

/* Only two canonical room-level events are admitted in v1. These payloads
 * are generated by the Room Owner. No general JSON relay or sensitive field
 * pass-through is permitted. Producer/schema changes require explicit tests.
 */
typedef struct event_cursor {
    const uint8_t *bytes;
    size_t length;
    size_t offset;
} event_cursor;

static bool take(event_cursor *c, const char *literal) {
    const size_t n = strlen(literal);
    if (c->offset > c->length ||
        n > c->length - c->offset ||
        memcmp(c->bytes + c->offset, literal, n) != 0)
        return false;
    c->offset += n;
    return true;
}

static bool positive_decimal(event_cursor *c, uint64_t *out) {
    uint64_t value = 0u;
    size_t count = 0u;
    if (c->offset >= c->length ||
        c->bytes[c->offset] < '1' || c->bytes[c->offset] > '9')
        return false;
    while (c->offset < c->length) {
        const uint8_t ch = c->bytes[c->offset];
        uint64_t digit;
        if (ch < '0' || ch > '9') break;
        digit = (uint64_t)(ch - '0');
        if (value > (UINT64_MAX - digit) / 10u)
            return false;
        value = value * 10u + digit;
        ++c->offset;
        ++count;
    }
    if (!count) return false;
    *out = value;
    return true;
}

bool mygames_outbox_public_event_validate(
    const uint8_t *payload, size_t size,
    uint64_t current_epoch, uint64_t event_sequence) {
    event_cursor c;
    uint64_t id = 0u, epoch = 0u, seq = 0u, field = 0u;
    bool is_expiration;
    size_t i;
    if (!payload || size < 70u || size > MYGAMES_STORE_EVENT_MAX ||
        !current_epoch || !event_sequence)
        return false;
    /* Canonical ASCII JSON only; escape sequences, controls, whitespace
     * and arbitrary extra fields are never passed through. */
    for (i = 0u; i < size; ++i)
        if (payload[i] < 0x20u || payload[i] > 0x7eu)
            return false;
    c = (event_cursor){payload, size, 0u};
    if (!take(&c, "{\"v\":1,\"type\":\"room.")) return false;
    if (take(&c, "command_accepted\"")) is_expiration = false;
    else if (take(&c, "session_expired\"")) is_expiration = true;
    else return false;
    if (!take(&c, ",\"room_id\":\"room-") ||
        !positive_decimal(&c, &id) || !take(&c, "\""))
        return false;
    if (is_expiration) {
        if (!take(&c, ",\"player_id\":\"") ||
            !positive_decimal(&c, &field) || !take(&c, "\""))
            return false;
    }
    if (!take(&c, ",\"room_epoch\":") ||
        !positive_decimal(&c, &epoch) ||
        epoch > current_epoch)
        return false;
    if (!is_expiration &&
        (!take(&c, ",\"revision\":") ||
         !positive_decimal(&c, &field)))
        return false;
    if (!take(&c, ",\"seq\":") ||
        !positive_decimal(&c, &seq) || seq != event_sequence ||
        !take(&c, "}") || c.offset != size)
        return false;
    return true;
}

mygames_outbox_result mygames_outbox_dispatch_one(
    mygames_room_store *store, mygames_outbox_publish_fn publish,
    void *context, uint64_t *out_sequence) {
    mygames_room_directory rooms;
    uint8_t message[MYGAMES_STORE_EVENT_MAX];
    size_t message_size = 0u;
    uint64_t epoch = 0u, current_sequence = 0u, event_sequence = 0u;
    mygames_store_status status;
    mygames_outbox_delivery delivered;
    if (!store || !publish) return MYGAMES_OUTBOX_FATAL;
    status = mygames_room_store_load(store, &rooms, &epoch, &current_sequence);
    if (status != MYGAMES_STORE_OK || !epoch) return MYGAMES_OUTBOX_FATAL;
    status = mygames_room_store_next_event(
        store, 0u, message, sizeof(message), &message_size, &event_sequence);
    if (status == MYGAMES_STORE_NOT_FOUND) return MYGAMES_OUTBOX_EMPTY;
    if (status != MYGAMES_STORE_OK || event_sequence == 0u ||
        event_sequence > current_sequence ||
        !mygames_outbox_public_event_validate(
            message, message_size, epoch, event_sequence))
        return MYGAMES_OUTBOX_FATAL;
    delivered = publish(context, MYGAMES_OUTBOX_MQTT_TOPIC,
                        message, message_size, epoch, event_sequence);
    if (delivered == MYGAMES_OUTBOX_DELIVERY_RETRY)
        return MYGAMES_OUTBOX_RETRY;
    if (delivered != MYGAMES_OUTBOX_DELIVERY_SETTLED)
        return MYGAMES_OUTBOX_FATAL;
    /* Broker QoS1 PUBACK is a positive delivery settlement. Outbox ACK is
     * a separate DB transaction, never a Game ACK. DB commit unknown is fatal.
     * If this ACK fails, next publisher invocation may duplicate the MQTT
     * event; consumers MUST deduplicate by its event ID/sequence. */
    status = mygames_room_store_ack_event(store, epoch, event_sequence);
    if (status != MYGAMES_STORE_OK) return MYGAMES_OUTBOX_FATAL;
    if (out_sequence) *out_sequence = event_sequence;
    return MYGAMES_OUTBOX_SENT;
}
